svg.script:
const R = {};
R.scriptRuns = true;
R.contentType = document.contentType;
R.hasBody = (typeof document.body) + " / " + String(document.body && document.body.tagName);
R.serviceWorkerAPI = typeof navigator.serviceWorker;
R.localStorageOK = (() => { try { localStorage.setItem("t","1"); return true } catch(e) { return false } })();
try { const d = document.createElement("div"); d.textContent = "made by createElement";
      document.getElementById("panel").appendChild(d);
      R.createElement = "ns='" + String(d.namespaceURI) + "' appended";
      R.createElementRenders = d.getBoundingClientRect().width > 0; } catch (e) { R.createElement = "throw:" + e.message; }
try { const d = document.createElementNS("http://www.w3.org/1999/xhtml", "div"); d.textContent = "made by createElementNS";
      document.getElementById("panel").appendChild(d);
      R.createElementNSRenders = (d.getBoundingClientRect().width > 0) + " color=" + getComputedStyle(d).color; }
catch (e) { R.createElementNSRenders = "throw:" + e.message; }
try { const box = document.createElementNS("http://www.w3.org/1999/xhtml","div");
      document.getElementById("panel").appendChild(box);
      box.innerHTML = "<b>bold</b><br><br>after two unclosed br tags";
      R.innerHTMLUnclosed = "parsed, len=" + box.textContent.length; }
catch (e) { R.innerHTMLUnclosed = "THREW " + e.name + ": " + e.message.slice(0,70); }
try { const box = document.createElementNS("http://www.w3.org/1999/xhtml","div");
      document.getElementById("panel").appendChild(box);
      box.innerHTML = "<i>italic</i><br/><br/>self-closing br"; R.innerHTMLClosed = "ok"; }
catch (e) { R.innerHTMLClosed = "THREW " + e.name; }
try { R.querySelectorAll = "found " + document.querySelectorAll("div,span,h2").length + " nodes"; }
catch (e) { R.querySelectorAll = "THREW " + e.name; }
window.__R = R;
document.getElementById("out").textContent = Object.entries(R).map(([k,v]) => k.padEnd(20) + " " + v).join("\n");
